#!/usr/bin/env node
// GENERATED by scripts/build-prompt-skill.ts in the Diagramatix repository — do not edit by hand.
// The two checkers below (checkPromptShapes and checkPromptBranches) are the ones Diagramatix itself runs on its prompts, transpiled.
// Dependency-free: needs only Node.js 18 or later.   Usage:  node check_prompt.mjs prompt.txt   |   cat prompt.txt | node check_prompt.mjs

/**
 * Two things a repository prompt can ask for that BPMN does not allow.
 *
 * Paul, 2026-09-03, reading V22.07: a message "in the middle of nowhere … A
 * missing Black-box Pool???", and an event that "should be an EMIE on Task
 * 'Escalate to delegated approver' probably?". Both were faithful renderings of
 * what the PROMPT asked for, so no amount of layout or generation work could
 * have fixed them — the instruction itself was wrong.
 *
 * Deterministic and free, like `checkPromptBranches`, so a prompt can be gated
 * on it rather than inspected. Both checks read the prompt's own house style,
 * which the master template fixes:
 *
 *   5. Edge-mounted (boundary) events
 *      "<interrupting|non-interrupting> <type> boundary event on <HOST>"
 *   6. Connectors → "Message flows:"
 *      "<source> → <target> (<what is carried>)"
 */
/**
 * A boundary event may be mounted ONLY on an activity — a task or a subprocess.
 * These are the words that name something else, so a host beginning with one is
 * an instruction the generator cannot carry out.
 */
const NOT_AN_ACTIVITY = /^(intermediate|message start|timer start|start event|end event|exclusive|inclusive|parallel|event[- ]based|terminate|escalation end|error end)\b/i;
/** The section-6 form for a message flow: "<a> → <b> (<payload>)". */
const MESSAGE_ARROW = /^(.*?)\s*(?:→|->)\s*(.*)$/;
export function checkPromptShapes(prompt, advice = false) {
    const lines = prompt.split(/\r?\n/);
    const issues = [];
    // A wrapped prompt breaks mid-phrase, so each instruction is rejoined with
    // its continuation lines before being read. Matching line by line would miss
    // every instruction the formatter happened to wrap — which is most of them.
    const joined = [];
    for (let i = 0; i < lines.length; i++) {
        const raw = lines[i];
        if (!raw.trim())
            continue;
        const indent = raw.match(/^\s*/)[0].length;
        let text = raw.trim();
        let j = i + 1;
        while (j < lines.length && lines[j].trim() && lines[j].match(/^\s*/)[0].length > indent) {
            text += " " + lines[j].trim();
            j++;
        }
        joined.push({ text: text.replace(/\s+/g, " "), line: i + 1 });
    }
    // Which steps each Expanded Subprocess holds, from its own line:
    //   Expanded Subprocess "<name>" (standard loop) containing, in order: <type> "<a>", <type> "<b>", …
    const norm = (s) => s.replace(/\s+/g, " ").trim().toLowerCase();
    const epMembers = new Map();
    for (const { text } of joined) {
        const m = text.match(/Expanded Subprocess\s+"([^"]+)"[^"]*?containing,?\s*in order:\s*(.*)$/i);
        if (m)
            epMembers.set(norm(m[1]), { name: m[1], members: new Set([...m[2].matchAll(/"([^"]+)"/g)].map((x) => norm(x[1]))) });
    }
    let inMessages = false;
    for (const { text, line } of joined) {
        if (/^Message flows:/i.test(text)) {
            inMessages = true;
            continue;
        }
        if (/^Sequence flows:/i.test(text) || /^\d\.\s/.test(text))
            inMessages = false;
        // (a) A boundary event mounted on something that is not an activity.
        const b = text.match(/boundary event on\s+"?([^"—]+?)"?\s*(?:—|-|,|$)/i);
        if (b && NOT_AN_ACTIVITY.test(b[1].trim())) {
            issues.push({
                line, kind: "boundary-on-non-activity",
                detail: `mounted on "${b[1].trim().slice(0, 60)}" — a boundary event can only be attached to a task or subprocess`,
            });
        }
        // (c) A boundary event on a step INSIDE an Expanded Subprocess whose exception path leads OUT of it (Paul, 2026-10-07: rule R8.45, the
        //     diagram check B41). An event on a child's rim sits inside the subprocess, so the path must stay inside; to leave, the event is
        //     mounted on the Expanded Subprocess itself. The destinations are every name quoted after "leading to" / "continues to".
        const bh = text.match(/boundary event on\s+(?:[A-Za-z-]+\s+){0,4}?"([^"]+)"/i);
        const lead = text.search(/\b(?:leading to|continues to)\b/i);
        if (bh && lead >= 0) {
            const owner = [...epMembers.values()].find((ep) => ep.members.has(norm(bh[1])));
            if (owner) {
                const outside = [...text.slice(lead).matchAll(/"([^"]+)"/g)].map((x) => x[1])
                    .find((d) => !owner.members.has(norm(d)) && norm(d) !== norm(owner.name));
                if (outside) {
                    issues.push({
                        line, kind: "boundary-leaves-subprocess",
                        detail: `mounted on "${bh[1]}", which is inside Expanded Subprocess "${owner.name}", but leads out of it to "${outside}" — mount the event on the Expanded Subprocess itself`,
                    });
                }
            }
        }
        // (d) A boundary event whose path goes STRAIGHT to an End event — a "silent failure" (Paul, 2026-10-08: rule R8.47, the diagram check
        //     B56). A task sits between them so a person can act when the exception occurs.
        // (e) An End event on a boundary event's line that is not a TERMINATE End event (rule R8.48, check B57): the exception ends the
        //     whole process.
        //     These two are ADVICE, not "cannot be drawn": generation puts the task in and sets the Terminate itself (R8.47 / R8.48), so a
        //     prompt that omits them still draws. They are reported only when asked for (`advice`) — by the prompt skill and the AI Generate
        //     console, which want the prompt right at the source — and not in the repository's "undrawable" counts.
        if (advice && /boundary event on/i.test(text)) {
            // Straight = from the word that starts the path, the next thing named is an End event (no task, subprocess or gateway in between).
            const from = text.search(/\b(?:triggers|leading to|leads to|continues to|goes to|ends? (?:in|at|with))\b/i);
            const after = from >= 0 ? text.slice(from) : "";
            const endAt = after.search(/\bEnd event\b/i);
            const straight = endAt >= 0 && !/\b(?:task|subprocess|activity|gateway)\b/i.test(after.slice(0, endAt));
            if (straight) {
                issues.push({
                    line, kind: "boundary-straight-to-end",
                    detail: "leads straight to an End event — a silent failure. Put a task between them (the event triggers a User task, which then ends in the End event)",
                });
            }
            for (const m of text.matchAll(/(Terminate\s+)?End event\s+"([^"]+)"/gi)) {
                if (!m[1]) {
                    issues.push({
                        line, kind: "exception-end-not-terminate",
                        detail: `the End event "${m[2].slice(0, 50)}" finishes an exception path — write it as Terminate End event "${m[2].slice(0, 50)}"`,
                    });
                }
            }
        }
        // (b) A message flow between two LANES. A message flow must cross a POOL
        //     boundary; between lanes of one pool it is a sequence flow, and if an
        //     outside participant was meant, that participant needs a pool.
        if (inMessages) {
            const m = text.match(MESSAGE_ARROW);
            if (m && /\blane\b/i.test(m[1]) && /\blane\b/i.test(m[2])) {
                issues.push({
                    line, kind: "message-within-pool",
                    detail: `${m[1].trim().slice(0, 40)} → ${m[2].trim().slice(0, 40)} — both ends are lanes of one pool`,
                });
            }
        }
    }
    return issues;
}

/**
 * Does every gateway in a generated prompt say where its branches GO?
 *
 * The master template has always required it — "Every diverging gateway is
 * matched by a named MERGE gateway that the branches rejoin, written as its own
 * line at the point they come together ... A branch that ends in its own End
 * event does not rejoin; say so" — but nothing checked. Paul hit the same
 * ambiguity from the other direction on 2026-09-01, reading a Technical
 * Description: "the Decisions are not terminated unambiguously".
 *
 * It matters because these prompts are the INPUT to regeneration. A branch that
 * simply stops tells the model nothing about whether the path rejoins, ends or
 * loops, so the model invents an answer and the diagram stops being the process
 * that was written down.
 *
 * THE UNIT IS THE GATEWAY, NOT THE BRANCH. The template deliberately puts the
 * merge on its own line AFTER the branch group rather than repeating it inside
 * every branch, so judging branches individually condemns the house style:
 *
 *     Exclusive gateway "Discrepancy type?"
 *     - branch "Quantity discrepancy": User task "Prepare quantity notice"
 *     - branch "Quality or damage discrepancy": User task "Prepare notice"
 *     Exclusive merge gateway "Discrepancy type"      <- resolves both
 *
 * A gateway is resolved when a merge line follows its branches, or when every
 * branch states its own fate. Only where NEITHER holds is a branch ambiguous.
 *
 * Deterministic and free: no AI call, so it can gate every prompt the way
 * `roundTripsOk` already gates parseability.
 */
/**
 * The ways a branch may finish on its own terms — each names a DESTINATION.
 *
 * Deliberately generous about wording. The catalogue says the same few things
 * several ways — "reach subprocess end" for "(exits subprocess)", "loop
 * continues" for "(loop repeats)", "gateway merge" for "merge gateway" — and
 * flagging a clear statement for its phrasing buries the branches that really
 * are ambiguous.
 *
 * What is NOT accepted is a destination naming no element: "continue to the
 * Finance lane" says which lane but not which step, and that is exactly the gap
 * that leaves a regeneration guessing.
 */
const SELF_TERMINATED = [
    // A branch that simply flows on to an element already named above. The type
    // word before the quoted name is what separates it from the case this check
    // exists for: `continues to User task "Assess claim"` names something that
    // can be drawn; `continues to the Legal lane` does not. Without this form
    // the template offered no legal way to say "and then the next task", and
    // the model resolved that by inventing a merge gateway with a single branch
    // in it (Paul, 2026-09-03: "Decisions, Decisions!!").
    /\bcontinues?\s+to\s+(?:the\s+)?(?:[A-Za-z][\w-]*\s+){0,3}(?:task|subprocess|gateway|event|activity)\s*"[^"]+"/i,
    /\bmerge\s+gateway\b/i,
    /\bgateway\s+merge\b/i, // the same thing, other word order
    /\bEnd event\b/i,
    /\bloops? (repeats?|continues?)\b/i,
    /\bexits?\b[^.]*\bsubprocess\b/i,
    /\bsubprocess end\b/i,
    /\breturns? to\b/i,
    /\bloops? back\b/i,
];
const BRANCH_RE = /^(\s*)-\s*branch\s*"(.*?)"\s*:/;
const GATEWAY_RE = /\bgateway\s*"(.*?)"/i;
const MERGE_RE = /\bmerge\s+gateway\b/i;
export function checkPromptBranches(prompt) {
    const lines = prompt.split(/\r?\n/);
    const indentOf = (l) => l.match(/^\s*/)[0].length;
    const issues = [];
    for (let i = 0; i < lines.length; i++) {
        const m = lines[i].match(BRANCH_RE);
        if (!m)
            continue;
        const base = m[1].length;
        // Only the FIRST branch of a group drives the check; the rest are collected
        // by the walk below. A branch's own body is indented DEEPER than it, so the
        // preceding sibling is found by stepping back over that body — checking
        // merely the previous non-empty line finds a body line and calls every
        // branch a first, which reports the same group once per branch.
        const isFirstOfGroup = (() => {
            for (let k = i - 1; k >= 0; k--) {
                if (lines[k].trim() === "")
                    continue;
                if (indentOf(lines[k]) > base)
                    continue; // this or a sibling's body
                const pm = lines[k].match(BRANCH_RE);
                return !(pm && pm[1].length === base);
            }
            return true;
        })();
        if (!isFirstOfGroup)
            continue;
        // The gateway this group hangs off: the nearest preceding line, at a
        // shallower indent, that names a gateway.
        let gateway = "(unnamed gateway)";
        for (let k = i - 1; k >= 0; k--) {
            if (lines[k].trim() === "")
                continue;
            if (indentOf(lines[k]) >= base && lines[k].match(BRANCH_RE))
                continue;
            const g = lines[k].match(GATEWAY_RE);
            if (g)
                gateway = g[1];
            break;
        }
        // Walk the whole group, gathering each branch's own text.
        const group = [];
        let cur = { line: i + 1, condition: m[2], parts: [lines[i].slice(m[0].length)], after: [] };
        let k = i + 1;
        let nestedBelow = -1;
        let resolvedByMerge = false;
        for (; k < lines.length; k++) {
            const line = lines[k];
            if (line.trim() === "")
                continue;
            const ind = indentOf(line);
            if (nestedBelow >= 0 && ind > nestedBelow)
                continue; // inside a sub-branch
            nestedBelow = -1;
            const bm = line.match(BRANCH_RE);
            if (bm && bm[1].length === base) { // the next sibling
                if (cur)
                    group.push(cur);
                cur = { line: k + 1, condition: bm[2], parts: [line.slice(bm[0].length)], after: [] };
                continue;
            }
            if (bm) { // a nested branch
                nestedBelow = bm[1].length;
                // Track the LAST nested group, not the first. A branch may hold several
                // — V23.07 "Accepted" runs a loop subprocess, then more steps, then a
                // closing gateway — and it is what follows the final one that decides
                // whether a continuation is still owed.
                if (cur) {
                    cur.nestedAt = k;
                    cur.after = [];
                }
                continue;
            }
            if (ind > base) { // this branch's body
                if (cur)
                    (cur.nestedAt === undefined ? cur.parts : cur.after).push(line);
                continue;
            }
            // Back out to the gateway's own level: this is where a merge would sit.
            if (MERGE_RE.test(line))
                resolvedByMerge = true;
            break;
        }
        if (cur)
            group.push(cur);
        if (resolvedByMerge)
            continue;
        const decided = group.map((b) => {
            const body = [...b.parts, ...b.after].join(" ").replace(/\s+/g, " ").trim();
            if (SELF_TERMINATED.some((re) => re.test(body)))
                return { b, body, ok: true };
            // A branch whose own text says nothing may still be closed by what hangs
            // BENEATH it. Excluding nested sub-branches (T3130) stops an inner End
            // event vouching for a parent that carries on afterwards — but when every
            // inner path ends AND nothing follows the nested group, the parent has no
            // continuation left to state. V23.07 "Yes — hardship eligible" is three
            // levels of gateway with an End event on every leaf.
            // No recursion is needed: the main loop reaches every nested group in its
            // own right and reports it there, so a parent only has to show it is not
            // still owing a continuation of its own.
            if (b.nestedAt !== undefined && !/\w/.test(b.after.join(" "))) {
                return { b, body, ok: true };
            }
            return { b, body, ok: false };
        });
        // A gateway needs no merge when only ONE branch survives: the others end,
        // and the survivor simply continues the line the gateway sits on, which the
        // layout already makes plain. V21.01 turns away an unreadable application
        // and carries the readable one straight on — nothing to join.
        //
        // Only where that survivor makes NO destination claim, though. One that does
        // and names a LANE rather than an element — "(continues to Legal lane via
        // sequence flow)" — is the very case this check exists for, and must not be
        // waved through merely because its sibling ended.
        const CLAIMS_A_DESTINATION = /\b(continues?|proceeds?|passes|goes|routes?|flows?)\b/i;
        const unresolved = decided.filter((d) => !d.ok);
        const closed = decided.length - unresolved.length;
        //
        // Restricted to a SIMPLE branch, too. One carrying a gateway of its own is
        // not quietly continuing the main line — it has structure whose ending has
        // to be readable on its own terms.
        if (unresolved.length === 1 && closed >= 1
            && unresolved[0].b.nestedAt === undefined
            && !CLAIMS_A_DESTINATION.test(unresolved[0].body))
            continue;
        for (const d of unresolved) {
            issues.push({ line: d.b.line, condition: d.b.condition, gateway, body: d.body });
        }
    }
    return issues;
}


// ── Structural checks (not part of the app's checkers) ───────────────────────────────────────────────────────────────────────
const SECTIONS = [
  [/^1\.\s*Pools\s*&\s*Lanes/im, "1. Pools & Lanes"],
  [/^2\.\s*Pool properties/im, "2. Pool properties"],
  [/^3\.\s*Layout/im, "3. Layout"],
  [/^4\.\s*Lane contents/im, "4. Lane contents in flow order"],
  [/^5\.\s*Edge-mounted/im, "5. Edge-mounted (boundary) events"],
  [/^6\.\s*Connectors/im, "6. Connectors"],
  [/^7\.\s*Data objects/im, "7. Data objects"],
];

export function checkStructure(prompt) {
  const issues = [];
  const lines = prompt.split(/\r?\n/);
  const lineOf = (re) => { const i = lines.findIndex((l) => re.test(l)); return i < 0 ? 0 : i + 1; };
  const first = lines.find((l) => l.trim());
  if (!first || !/^BPMN:\s/.test(first.trim())) issues.push({ line: 1, kind: "opening-line", detail: 'the prompt must open with one line: "BPMN: <Process Name> — <one clause>."' });
  let prev = -1;
  for (const [re, name] of SECTIONS) {
    const at = lines.findIndex((l) => re.test(l.trim()));
    if (at < 0) { issues.push({ line: 0, kind: "missing-section", detail: "missing section " + name }); continue; }
    if (at < prev) issues.push({ line: at + 1, kind: "section-order", detail: name + " is out of order" });
    prev = Math.max(prev, at);
  }
  const ds = lineOf(/data store/i);
  if (ds) issues.push({ line: ds, kind: "data-store", detail: "a Data Store is never used — a system of record is the system's black-box pool" });
  const ni = lineOf(/non-interrupting/i);
  if (ni) issues.push({ line: ni, kind: "non-interrupting", detail: "every edge-mounted event is interrupting; do not write non-interrupting" });
  const lb = lineOf(/\b(then|goes?|going)\s+back\s+to\b|\bloops?\s+back\s+to\b/i);
  if (lb) issues.push({ line: lb, kind: "loop-back", detail: "repetition is a standard-loop subprocess, never a flow back to an earlier element" });
  const nx = lineOf(/continues?\s+to\s+(the\s+)?next\s+(task|step|activity)\b/i);
  if (nx) issues.push({ line: nx, kind: "destination-not-an-element", detail: '"continue to the next task" names nothing that can be drawn — name the element' });
  const ln = lineOf(/continues?\s+to\s+the\s+[^"\n]*\blane\b/i);
  if (ln) issues.push({ line: ln, kind: "destination-not-an-element", detail: "a lane is not a destination — name the element it continues to" });
  return issues;
}

// ── Command line ─────────────────────────────────────────────────────────────────────────────────────────────────────────────
export function runChecks(prompt) {
  return [
    ...checkStructure(prompt),
    ...checkPromptShapes(prompt, true).map((i) => ({ line: i.line, kind: i.kind, detail: i.detail })),
    ...checkPromptBranches(prompt).map((i) => ({ line: i.line, kind: "branch-without-destination", detail: 'gateway "' + i.gateway + '", branch "' + i.condition + '" never says where it goes' })),
  ].sort((a, b) => a.line - b.line);
}

async function main() {
  const { readFileSync } = await import("node:fs");
  const arg = process.argv[2];
  let text;
  if (arg) text = readFileSync(arg, "utf8");
  else { const chunks = []; for await (const c of process.stdin) chunks.push(c); text = Buffer.concat(chunks).toString("utf8"); }
  if (!text.trim()) { console.error("Give a prompt file as the argument, or pipe the prompt in."); process.exit(2); }
  const issues = runChecks(text);
  if (issues.length === 0) { console.log("OK — no issues found."); return; }
  for (const i of issues) console.log((i.line ? "line " + i.line : "prompt").padEnd(9) + " [" + i.kind + "] " + i.detail);
  console.log("\n" + issues.length + " issue" + (issues.length === 1 ? "" : "s") + " found.");
  process.exitCode = 1;
}

import { pathToFileURL } from "node:url";
if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) main();
